package solution

import (
	"encoding/json"
	"testing"
	"time"
)

func TestDurationDistributionBucketsAndBoundaryValues(t *testing.T) {
	bounds := []time.Duration{10 * time.Nanosecond, 20 * time.Nanosecond}
	d, err := NewDurationDistribution(bounds)
	if err != nil {
		t.Fatalf("NewDurationDistribution returned error: %v", err)
	}
	bounds[0] = time.Second

	for _, duration := range []time.Duration{0, 10 * time.Nanosecond, 11 * time.Nanosecond, 20 * time.Nanosecond, 21 * time.Nanosecond} {
		if err := d.Add(duration); err != nil {
			t.Fatalf("Add(%v) returned error: %v", duration, err)
		}
	}
	got, err := json.Marshal(d)
	if err != nil {
		t.Fatalf("Marshal returned error: %v", err)
	}
	want := `{"bounds_ns":[10,20],"counts":[2,2,1]}`
	if string(got) != want {
		t.Fatalf("JSON = %s, want %s", got, want)
	}
}

func TestDurationDistributionRejectsBadBounds(t *testing.T) {
	cases := [][]time.Duration{
		{0},
		{-1},
		{2, 2},
		{3, 2},
		{1, 0},
	}
	for _, bounds := range cases {
		if got, err := NewDurationDistribution(bounds); err == nil || got != nil {
			t.Errorf("NewDurationDistribution(%v) returned (%#v, %v), want nil and error", bounds, got, err)
		}
	}
}

func TestDurationDistributionEmptyAndZeroValue(t *testing.T) {
	for _, bounds := range [][]time.Duration{nil, {}} {
		d, err := NewDurationDistribution(bounds)
		if err != nil {
			t.Fatalf("NewDurationDistribution(%v): %v", bounds, err)
		}
		got, err := d.MarshalJSON()
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != `{"bounds_ns":[],"counts":[0]}` {
			t.Fatalf("empty distribution JSON = %s", got)
		}
	}

	var zero DurationDistribution
	got, err := zero.MarshalJSON()
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != `{"bounds_ns":[],"counts":[0]}` {
		t.Fatalf("zero-value JSON = %s", got)
	}
}

func TestDurationDistributionNegativeAddIsAtomic(t *testing.T) {
	d, _ := NewDurationDistribution([]time.Duration{5})
	if err := d.Add(4); err != nil {
		t.Fatal(err)
	}
	before, _ := d.MarshalJSON()
	if err := d.Add(-1); err == nil {
		t.Fatal("negative duration was accepted")
	}
	after, _ := d.MarshalJSON()
	if string(after) != string(before) {
		t.Fatalf("counts changed after rejected Add: before=%s after=%s", before, after)
	}
}

func TestDurationDistributionReturnedJSONIsStable(t *testing.T) {
	d, _ := NewDurationDistribution([]time.Duration{5})
	first, _ := d.MarshalJSON()
	firstCopy := append([]byte(nil), first...)
	if err := d.Add(5); err != nil {
		t.Fatal(err)
	}
	if string(first) != string(firstCopy) || string(first) != `{"bounds_ns":[5],"counts":[0,0]}` {
		t.Fatalf("previous JSON changed after Add: %s", first)
	}
}

func TestAssemblyStatsString(t *testing.T) {
	tests := []struct {
		stats AssemblyStats
		want  string
	}{
		{AssemblyStats{}, "assembly: none"},
		{AssemblyStats{Transactions: 3}, "assembly: transactions=3"},
		{AssemblyStats{ProcessingTime: 1500 * time.Millisecond}, "assembly: processing=1.5s"},
		{AssemblyStats{Transactions: 2, ProcessingTime: time.Second, Retries: 4, Rejected: 1}, "assembly: transactions=2, processing=1s, retries=4, rejected=1"},
		{AssemblyStats{Transactions: -2, ProcessingTime: -time.Millisecond, Retries: -3, Rejected: -4}, "assembly: transactions=-2, processing=-1ms, retries=-3, rejected=-4"},
	}
	for _, tc := range tests {
		if got := tc.stats.String(); got != tc.want {
			t.Errorf("(%#v).String() = %q, want %q", tc.stats, got, tc.want)
		}
	}
}

